<?php
require_once __DIR__ . "/../config/language.php"; require_once __DIR__ . "/../config/session.php"; require_once __DIR__ . "/../config/database.php"; require_once __DIR__ . "/../config/profile_setup.php";
if(!isset($_SESSION['user_id']) || (int)$_SESSION['role_id']!==1){header("Location: ../login.php");exit();}
$msg=''; $err='';
if(isset($_POST['decision'])){ $id=(int)($_POST['request_id']??0); $decision=$_POST['decision']==='approve'?'Approved':'Rejected'; $q=mysqli_prepare($conn,"SELECT * FROM profile_change_requests WHERE request_id=? AND status='Pending' LIMIT 1"); mysqli_stmt_bind_param($q,'i',$id); mysqli_stmt_execute($q); $r=mysqli_stmt_get_result($q); $req=$r?mysqli_fetch_assoc($r):null; mysqli_stmt_close($q); if(!$req){$err='Request not found or already reviewed.';} elseif($decision==='Approved'){ $q=mysqli_prepare($conn,"UPDATE users SET full_name=?,email=?,phone=?,profile_photo=COALESCE(?,profile_photo) WHERE user_id=?"); mysqli_stmt_bind_param($q,'ssssi',$req['full_name'],$req['email'],$req['phone'],$req['profile_photo'],$req['user_id']); mysqli_stmt_execute($q); mysqli_stmt_close($q); $q=mysqli_prepare($conn,"UPDATE profile_change_requests SET status='Approved',reviewed_at=NOW(),reviewed_by=? WHERE request_id=?"); mysqli_stmt_bind_param($q,'ii',$_SESSION['user_id'],$id); mysqli_stmt_execute($q); mysqli_stmt_close($q);
            $nt=mysqli_prepare($conn,"INSERT INTO user_notifications(user_id,type,title,message,link) VALUES(?, 'profile_approved', ?, ?, ?)");
            if($nt){$ntitle='Profile change approved';$nmessage='Your profile changes were approved by an administrator.';$nlink='profile.php';mysqli_stmt_bind_param($nt,'isss',$req['user_id'],$ntitle,$nmessage,$nlink);mysqli_stmt_execute($nt);mysqli_stmt_close($nt);}
            $msg='Profile change approved successfully.';} else { $q=mysqli_prepare($conn,"UPDATE profile_change_requests SET status='Rejected',reviewed_at=NOW(),reviewed_by=? WHERE request_id=?"); mysqli_stmt_bind_param($q,'ii',$_SESSION['user_id'],$id); mysqli_stmt_execute($q); mysqli_stmt_close($q);
            $nt=mysqli_prepare($conn,"INSERT INTO user_notifications(user_id,type,title,message,link) VALUES(?, 'profile_rejected', ?, ?, ?)");
            if($nt){$ntitle='Profile change rejected';$nmessage='Your profile changes were rejected by an administrator.';$nlink='profile.php';mysqli_stmt_bind_param($nt,'isss',$req['user_id'],$ntitle,$nmessage,$nlink);mysqli_stmt_execute($nt);mysqli_stmt_close($nt);}
            $msg='Profile change rejected.'; } }
$requests=mysqli_query($conn,"SELECT p.*,u.username,u.full_name AS current_name FROM profile_change_requests p JOIN users u ON p.user_id=u.user_id WHERE p.status='Pending' ORDER BY p.requested_at ASC");
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile Approvals</title><link rel="stylesheet" href="css/dashboard.css"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container mt-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>✅ Profile Change Approvals</h2><p class="text-muted mb-0">Review employee profile changes before they become active.</p></div><a href="dashboard.php" class="btn btn-secondary">← Dashboard</a></div><?php if($msg):?><div class="alert alert-success"><?php echo htmlspecialchars($msg);?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?php echo htmlspecialchars($err);?></div><?php endif;?><div class="card shadow"><div class="card-body"><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>User</th><th>Requested Name</th><th>Email</th><th>Phone</th><th>Photo</th><th>Requested At</th><th>Action</th></tr></thead><tbody><?php if(!$requests||mysqli_num_rows($requests)===0):?><tr><td colspan="7" class="text-center">No pending profile changes.</td></tr><?php else: while($r=mysqli_fetch_assoc($requests)):?><tr><td><?php echo htmlspecialchars($r['username']);?><br><small><?php echo htmlspecialchars($r['current_name']);?></small></td><td><?php echo htmlspecialchars($r['full_name']);?></td><td><?php echo htmlspecialchars($r['email']??'');?></td><td><?php echo htmlspecialchars($r['phone']??'');?></td><td><?php if($r['profile_photo']):?><img src="../<?php echo htmlspecialchars($r['profile_photo']);?>" style="width:55px;height:55px;border-radius:50%;object-fit:cover"><?php else:?>No change<?php endif;?></td><td><?php echo htmlspecialchars($r['requested_at']);?></td><td><form method="post" class="d-inline"><input type="hidden" name="request_id" value="<?php echo (int)$r['request_id'];?>"><button name="decision" value="approve" class="btn btn-success btn-sm">Approve</button></form> <form method="post" class="d-inline"><input type="hidden" name="request_id" value="<?php echo (int)$r['request_id'];?>"><button name="decision" value="reject" class="btn btn-danger btn-sm">Reject</button></form></td></tr><?php endwhile; endif;?></tbody></table></div></div></div></div></body></html>